"""CloudDrive wire schema with a plugin-private protobuf registry.

Schema from DDSRem-Dev/clouddrive2-client 0.3.0 (MIT).
Never register CloudDrive names in the process-wide descriptor/symbol pools.
"""
import base64
from types import SimpleNamespace
from google.protobuf import descriptor_pool, descriptor_pb2, empty_pb2, timestamp_pb2, message_factory
import grpc

_pool = descriptor_pool.DescriptorPool()
for _dependency in (descriptor_pb2, empty_pb2, timestamp_pb2):
    _pool.AddSerializedFile(_dependency.DESCRIPTOR.serialized_pb)
DESCRIPTOR = _pool.AddSerializedFile(base64.b64decode(
    ''
))
proto = SimpleNamespace(**{
    name: message_factory.GetMessageClass(descriptor)
    for name, descriptor in DESCRIPTOR.message_types_by_name.items()
})

class CloudDriveClient:
    def __init__(self, address):
        self.channel = grpc.insecure_channel(address)
        self.stub = SimpleNamespace()
        service = DESCRIPTOR.services_by_name['CloudDriveFileSrv']
        for method in service.methods:
            factory = getattr(self.channel, ('stream' if method.client_streaming else 'unary')
                              + '_' + ('stream' if method.server_streaming else 'unary'))
            response = message_factory.GetMessageClass(method.output_type)
            setattr(self.stub, method.name, factory(
                '/' + service.full_name + '/' + method.name,
                request_serializer=lambda request: request.SerializeToString(),
                response_deserializer=response.FromString))

    def close(self):
        self.channel.close()
